#!/usr/bin/env bash
# The well-known types in wkt/, generated by the plugin and committed as part
# of the pb_wire package (decision 0007). Checks that wkt/ is what the plugin
# generates now, and `goose check`s each file, failing on warnings too.
# Usage: scripts/wkt.sh [--update]
# Run --update after an intended generator change, and review the diff.
# Env: PLUGIN (default: scripts/build_plugin.sh), PROTOC, GOOSE,
#      PROTOC_INCLUDE (default: the pinned protoc's include directory)
set -uo pipefail

root="$(cd "$(dirname "$0")/.." && pwd)"
[ -d "$root/.tools/bin" ] && export PATH="$root/.tools/bin:$PATH"
protoc="${PROTOC:-protoc}"
goose="${GOOSE:-goose}"

update=0
case "${1:-}" in
  "") ;;
  --update) update=1 ;;
  *) echo "usage: $0 [--update]" >&2; exit 2 ;;
esac

if [ -z "${PLUGIN:-}" ]; then
  "$root/scripts/build_plugin.sh" || { echo "error: scripts/build_plugin.sh failed" >&2; exit 1; }
  PLUGIN="$root/build/protoc-gen-goose"
fi

includes=()
inc="${PROTOC_INCLUDE:-$(ls -d "$root"/.tools/protoc-*/include 2>/dev/null | head -1)}"
[ -n "$inc" ] && includes+=(-I "$inc")

tmp="$(mktemp -d)"; trap 'rm -rf "$tmp"' EXIT
mkdir "$tmp/gen"
"$protoc" --plugin=protoc-gen-goose="$PLUGIN" --goose_out=wkt:"$tmp/gen" "${includes[@]}" \
  google/protobuf/any.proto google/protobuf/duration.proto \
  google/protobuf/empty.proto google/protobuf/field_mask.proto \
  google/protobuf/struct.proto google/protobuf/timestamp.proto \
  google/protobuf/wrappers.proto || { echo "FAIL protoc"; exit 1; }

bad=0
if [ $update = 1 ]; then
  rm -rf "$root/wkt"
  cp -R "$tmp/gen/wkt" "$root/wkt"
elif ! diff -ruN "$root/wkt" "$tmp/gen/wkt" >"$tmp/diff"; then
  echo "FAIL wkt/ differs from what the plugin generates"
  sed "s#$tmp/gen/wkt#generated#g" "$tmp/diff"
  echo "  (run scripts/wkt.sh --update to accept)"
  bad=1
fi

mkdir "$tmp/chk"
"$root/scripts/vendor_runtime.sh" "$tmp/chk"
for f in "$root"/wkt/*.goose; do
  mod="$(basename "$f" .goose)"
  echo "import pb_wire.wkt.$mod;" > "$tmp/chk/check_root.goose"
  if ! (cd "$tmp/chk" && "$goose" check check_root.goose) >"$tmp/log" 2>&1; then
    echo "FAIL wkt/$mod.goose: goose check failed"
    grep -v '^parsed ok\|^typechecked ok\|^bce:' "$tmp/log" | sed 's/^/    /'
    bad=1
  elif grep -q 'warning:' "$tmp/log"; then
    echo "FAIL wkt/$mod.goose: goose check warned"
    grep 'warning:' "$tmp/log" | sed 's/^/    /'
    bad=1
  else
    echo "ok   wkt/$mod.goose"
  fi
done
exit $bad
